wsc:message.wsc:body:
%dw 2.0
output application/xml
---
{
  findWithBalcony: {
    priceType: vars.priceType,
    balconyType: vars.balconyType
  }
}

ee:message.ee:set-attributes:
%dw 2.0
output application/java
---
attributes ++ {
  statusCode: payload.status default 200,
  headers: { "Content-Type": payload.mediaType default "application/xml" }
}

